def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []

    # Each object is a four-armed shape surrounding a zero-valued center.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r - 1][c] == 2 and
                grid[r + 1][c] == 2 and grid[r][c - 1] == 2 and
                grid[r][c + 1] == 2):
                centers.append((r, c))

    # Connect only consecutive centers sharing a row or column.
    for r in range(h):
        row_centers = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(row_centers, row_centers[1:]):
            for c in range(a + 1, b):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        col_centers = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(col_centers, col_centers[1:]):
            for r in range(a + 1, b):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
